      "unit": 7,
      "method": "將交點化為直線與圓的聯立；相切用圓心到線距離等於半徑，割線用弦長或判別式。",
      "focus": "將雷射視為正斜率射線，用圓心到直線距離與半徑比較判斷是否擊中。",
