    "1:1:112-數A-8": {
      "id": "1:1:112-數A-8",
      "key": "112-數A-8",
      "book": 1,
      "unit": 1,
      "method": "把第 n 項或下一步寫清楚，利用等差、等比或遞迴關係逐步推算。",
      "focus": "以獨立重複試驗的補事件得到至少一次中獎機率，再檢查相鄰項及多次中獎敘述。",
      "scope": "此處為關聯認列，以下先交代本單元的切入點，再列完整推導；完成全題還須結合第 4A 冊 數學 4A／第 7 單元 條件機率與貝氏定理。",
      "steps": [
        "補事件為 n 次都不中，所以 pₙ=1−0.9ⁿ。",
        "pₙ₊₁−pₙ=0.1×0.9ⁿ>0，故（1）對；p₃=1−0.729=0.271，不是 0.3；相鄰差不固定，故（2）（3）錯。",
        "第一次不中且第二次中，機率為 0.9×0.1=0.09，正好等於 p₂−p₁=0.19−0.1，故（4）對。",
        "以 n=2 為例，至少中兩次為 0.01，但 p₂²=0.0361，故（5）錯。"
      ],
      "answer": "選項（1）、（4）"
    },
    "1:1:112-數A-9": {
      "id": "1:1:112-數A-9",
      "key": "112-數A-9",
      "book": 1,
      "unit": 1,
      "method": "把第 n 項或下一步寫清楚，利用等差、等比或遞迴關係逐步推算。",
      "focus": "以底數 3 的對數律化簡等比數列，再按交錯符號配對加總並解項數不等式。",
      "scope": "此處為關聯認列，以下先交代本單元的切入點，再列完整推導；完成全題還須結合第 3A 冊 數學 3A／第 6 單元 對數與對數律。",
      "steps": [
        "aₖ=3(3√3)^(k−1)，所以 log₃aₖ=1+(3/2)(k−1)。",
        "若 n 為偶數，每兩項相減均為 −3/2，交錯和為 −3n/4，不可能大於 18。",
        "若 n=2m+1，前 2m 項和為 −3m/2，最後項為 1+3m，總和=1+3m/2=(3n+1)/4。",
        "要求 (3n+1)/4>18，得 n>71/3，並須為奇數。選項中的 25、27 符合。"
      ],
      "answer": "選項（3）、（5），n=25 或 27"
    },
