    "1:5:112-數A-6": {
      "id": "1:5:112-數A-6",
      "key": "112-數A-6",
      "book": 1,
      "unit": 5,
      "method": "先判斷哪些物件只需選取、不計順序，使用組合數及分組計數。",
      "focus": "把立方體頂點坐標化，求各種空間內積及其出現次數，再計算期望值。",
      "scope": "此處為關聯認列，以下先交代本單元的切入點，再列完整推導；完成全題還須結合第 2 冊 數學 2／第 7 單元 數學期望值、第 4A 冊 數學 4A／第 3 單元 空間向量的運算。",
      "steps": [
        "取 O 為原點，三條相鄰稜為坐標軸。其餘七頂點都是 (0,1) 分量組成、但不全為 0 的向量。",
        "任一坐標方向共有四個頂點的分量為 1；從七頂點任選相異兩點，共 C(7,2)=21 對，其中該方向兩分量同為 1 的有 C(4,2)=6 對。",
        "因此每一坐標乘積的期望值為 6/21=2/7。",
        "內積等於三個坐標乘積相加，故期望值=3×2/7=6/7。"
      ],
      "answer": "選項（3），6/7"
    },
    "1:5:113-數A-5": {
      "id": "1:5:113-數A-5",
      "key": "113-數A-5",
      "book": 1,
      "unit": 5,
      "method": "先判斷哪些物件只需選取、不計順序，使用組合數及分組計數。",
      "focus": "利用中位數的排序限制鎖定兩組中項，再從兩側數字以組合選取分組。",
      "scope": "依本單元方法展開推導；計算沿用學習路徑中較早學過的基本代數與幾何。",
      "steps": [
        "每組 25 個數，其中位數是第 13 個數。設兩中位數為相鄰的 k、k+1。比 k 小的數恰有 24 個，因為兩組各需 12 個較小數，所以 k=25。",
        "甲組中位數 25，乙組中位數 26。從 1～24 選 12 個給甲，再從 27～50 選 12 個給甲，其餘自動給乙，故有 C(24,12)² 種。"
      ],
      "answer": "選項（4）；C(24,12)²"
    },
    "1:5:113-數B-17": {
      "id": "1:5:113-數B-17",
      "key": "113-數B-17",
      "book": 1,
      "unit": 5,
      "method": "先判斷哪些物件只需選取、不計順序，使用組合數及分組計數。",
      "focus": "等差三內角的中角必為 60 度，配合圓周角與十二等分點計算無序三角形數。",
      "scope": "依本單元方法展開推導；計算沿用學習路徑中較早學過的基本代數與幾何。",
      "steps": [
        "三內角成等差且和為 180°，故中間角為 60°。圓周 12 等分，每個小弧 30°，其對應圓周角 15°；三段間隔（以小弧數計）必為 4−d、4、4+d，其中 d=0、1、2、3。",
        "d=0 時為正三角形，共 12/3=4 個。d=1、2、3 時三間隔不同，順時針排列有兩種循環順序；各順序可從 12 個點開始，得每類 24 個。",
        "總數 4+3×24=76。此計數已依循環順序排除同一三角形重複起算。"
      ],
      "answer": "76 個"
    },
    "1:5:114-數A-15": {
      "id": "1:5:114-數A-15",
      "key": "114-數A-15",
      "book": 1,
      "unit": 5,
      "method": "先判斷哪些物件只需選取、不計順序，使用組合數及分組計數。",
      "focus": "依首次累積第三個正面時的次數計算各購價機率，再求金額期望值。",
      "scope": "此處為關聯認列，以下先交代本單元的切入點，再列完整推導；完成全題還須結合第 2 冊 數學 2／第 7 單元 數學期望值。",
      "steps": [
        "恰在第 3 次取得第 3 個正面的機率為 1/8；恰在第 4 次為 C(3,2)/16=3/16；恰在第 5 次為 C(4,2)/32=3/16。",
        "5 次仍不到 3 個正面的機率為 [C(5,0)+C(5,1)+C(5,2)]/32=1/2。",
        "期望金額為 240/8+320×3/16+400×3/16+480/2=30+60+75+240=405 元。"
      ],
      "answer": "405 元"
    },
