    "1:6:110-數學-7": {
      "id": "1:6:110-數學-7",
      "key": "110-數學-7",
      "book": 1,
      "unit": 6,
      "method": "確認樣本結果等可能，算有利結果數除以總數，或使用補事件。",
      "focus": "前 3 個選項可由表格、機率及補事件判斷；後 2 個選項須反向條件機率，不能直接用每列機率判斷。",
      "scope": "此處為部分對應認列，以下先交代本單元的切入點，再列完整推導；完成全題還須結合第 4A 冊 數學 4A／第 7 單元 條件機率與貝氏定理、第 4B 冊 數學 4B／第 5 單元 貝氏定理。",
      "steps": [
        "（1）實際 8 看成 8 的機率是 0.4<0.5，錯。（2）實際 6 看錯機率為 1−0.4=0.6，對。",
        "（3）6、8、9 看錯機率依序為 0.6、0.6、0.5，所以 9 最低，對。",
        "各實際數字受觀察次數相同，因此已知看成 6，實際是 6 的條件機率為 0.4/(0.4+0.3+0.2)=4/9<1/2，（4）對。",
        "已知看成 9，實際是 9 的機率為 0.5/(0.2+0.1+0.5)=5/8<2/3，（5）錯。"
      ],
      "answer": "選項（2）、（3）、（4）"
    },
    "1:6:110-數學-12": {
      "id": "1:6:110-數學-12",
      "key": "110-數學-12",
      "book": 1,
      "unit": 6,
      "method": "確認樣本結果等可能，算有利結果數除以總數，或使用補事件。",
      "focus": "由有利排列數除以全部排列數求 P(A)、P(B)、P(C) 及交集機率；整題仍需條件機率。",
      "scope": "此處為部分對應認列，以下先交代本單元的切入點，再列完整推導；完成全題還須結合第 4A 冊 數學 4A／第 7 單元 條件機率與貝氏定理、第 4B 冊 數學 4B／第 4 單元 條件機率。",
      "steps": [
        "同色球不區分，總排列數為 7!/(2!2!3!)=210。黑球相鄰視為一塊，有 6!/(2!3!)=60 種，故 P(A)=2/7<P(B)=5/7，（1）錯。",
        "紅球互不相鄰：先排 4 個非紅球，有 4!/(2!2!)=6 種，從 5 個空隙選 3 個放紅球，有 C(5,3)=10 種，故 P(C)=60/210=2/7，（2）對。",
        "A∩C：先排 BB 塊與兩個白球，有 3!/2!=3 種，從 4 空隙選 3 個放紅球，共 12 種。",
        "所以 P(C|A)=12/60=1/5；P(C|B)=(60−12)/(210−60)=8/25。代入（3）得 2×1/5+5×8/25=2，並非小於 2；（4）恰等於 0.2；（5）8/25>0.3。故僅（2）、（5）。"
      ],
      "answer": "選項（2）、（5）"
    },
    "1:6:110-數學-C": {
      "id": "1:6:110-數學-C",
      "key": "110-數學-C",
      "book": 1,
      "unit": 6,
      "method": "確認樣本結果等可能，算有利結果數除以總數，或使用補事件。",
      "focus": "將符合乘積為完全平方數的三數組合數除以 84，求得所需機率；不涉及條件機率。",
      "scope": "依本單元方法展開推導；計算沿用學習路徑中較早學過的基本代數與幾何。",
      "steps": [
        "共有 C(9,3)=84 組。把各數去掉平方因數後，1、4、9 的平方自由部分是 1；2、8 是 2；其餘 3、5、6、7 分別保持不變。乘積為平方等價於每個質因數的總指數均為偶數。",
        "合格組合為 (1,4,9)；平方數配 (2,8) 的 (1,2,8)、(2,4,8)、(2,8,9)；及平方自由部分為 2、3、6 的 (2,3,6)、(3,6,8)。共 6 組。",
        "因此機率為 6/84=1/14。"
      ],
      "answer": "1/14"
    },
