    "4:5:110-數學-B": {
      "id": "4:5:110-數學-B",
      "key": "110-數學-B",
      "book": 4,
      "unit": 5,
      "method": "先找法向量及平面上一點，再用平面方程、正射影與點面距離公式。",
      "focus": "以法向量和平面方程式表示答案；還須第 6 單元從直線式讀出方向，檢查包含、平行且不相交的條件。",
      "scope": "此處為關聯認列，以下先交代本單元的切入點，再列完整推導；完成全題還須結合第 4A 冊 數學 4A／第 6 單元 空間中的直線。",
      "steps": [
        "L₁ 方向向量為 (2,−3,−5)，L₂ 方向向量為 (0,2,3)。E 包含 L₁ 且平行 L₂，所以法向量同時垂直兩方向。",
        "設法向量 (1,p,q)，解 2−3p−5q=0、2p+3q=0，得 p=−6、q=4。",
        "L₁ 通過原點，故 E：x−6y+4z=0。再代 L₂ 上點 (1,1,1)，左式為 −1≠0，確認整條 L₂ 不在平面上且不相交。"
      ],
      "answer": "x−6y+4z=0"
    },
    "4:5:110-數學-G": {
      "id": "4:5:110-數學-G",
      "key": "110-數學-G",
      "book": 4,
      "unit": 5,
      "method": "先找法向量及平面上一點，再用平面方程、正射影與點面距離公式。",
      "focus": "設底面為 z＝0，從距離條件求 D 後，可由點到平面距離或垂直坐標求高。此為較後階段的坐標解法。",
      "scope": "此處採本單元可用的替代解法；題幹給定的條件與已列前題結果一併使用。",
      "steps": [
        "取 A=(0,0,0)，B=(4√6,0,0)。由 AC=4√6、cos∠BAC=1/3，可取 C=(4√6/3,16√3/3,0)。",
        "設 D=(x,y,z)，AD²=96、BD²=CD²=64。前兩距離平方相減得 8√6x=128，所以 x=8√6/3。",
        "再由 AD²−CD²=32，得 Cₓx+Cᵧy=64，解 y=8√3/3。代回 x²+y²+z²=96，得 z²=32。",
        "ABC 所在平面為 z=0，因此所求距離為 |z|=4√2。此版只用坐標與距離平方；平面 z=0 的距離可直接看成垂直高度。"
      ],
      "answer": "4√2"
    },
    "4:5:111-數A-16": {
      "id": "4:5:111-數A-16",
      "key": "111-數A-16",
      "book": 4,
      "unit": 5,
      "method": "先找法向量及平面上一點，再用平面方程、正射影與點面距離公式。",
      "focus": "由直線及兩平面的投影關係辨識垂直平面，利用法向量與包含直線的條件求平面式。",
      "scope": "依本單元方法展開推導；計算沿用學習路徑中較早學過的基本代數與幾何。",
      "steps": [
        "把 L 寫成參數式：(x,y,z)=(2,−1,0)+t(2,1,−1/2)，可取方向向量 v=(4,2,−1)。",
        "原平面的法向量為 n=(1,−1,2)。因原平面內的另一條直線投影到 E 後縮成 L，兩平面須互相垂直，所以 E 的法向量同時垂直 n 與 v。",
        "計算 v×n=(3,−9,−6)，可取 nE=(1,−3,−2)。代入 L 上的 (2,−1,0)，常數為 5。",
        "故 E 為 x−3y−2z=5；也可直接檢查它包含 L，且 nE·n=0。"
      ],
      "answer": "E：x−3y−2z=5"
    },
