    "5:8:112-數B-7": {
      "id": "5:8:112-數B-7",
      "key": "112-數B-7",
      "book": 5,
      "unit": 8,
      "method": "比較截平面與圓錐軸、母線的角度，依定義區分橢圓、拋物線及雙曲線。",
      "focus": "依圓錐母線與截平面的平行關係判斷牆上、地板上的圓錐截痕種類。",
      "scope": "依本單元方法展開推導；計算沿用學習路徑中較早學過的基本代數與幾何。",
      "steps": [
        "光錐頂角 60°，半頂角為 30°。截痕為拋物線，代表牆面與其中一條母線平行。",
        "在垂直牆地交線的截面看，光錐軸與牆面夾 30°，所以與地板夾 60°。",
        "地板與軸的夾角 60° 大於半頂角 30°，會截成橢圓；又地板不垂直軸，不是圓。",
        "因此是長短軸不等的橢圓。"
      ],
      "answer": "選項（4），長短軸不相等的橢圓"
    },
    "5:8:114-數B-5": {
      "id": "5:8:114-數B-5",
      "key": "114-數B-5",
      "book": 5,
      "unit": 8,
      "method": "比較截平面與圓錐軸、母線的角度，依定義區分橢圓、拋物線及雙曲線。",
      "focus": "平面與圓錐軸平行，依截平面與兩錐面的關係辨識雙曲線截痕。",
      "scope": "依本單元方法展開推導；計算沿用學習路徑中較早學過的基本代數與幾何。",
      "steps": [
        "M 繞 L 形成上下兩葉直圓錐，L 為其軸。與軸平行、且不包含軸的平面會穿過兩葉，截痕為雙曲線。",
        "這裡「平面與直線平行」採課本定義，兩者無交點；若包含軸才會得到兩相交直線，並非題設。"
      ],
      "answer": "選項（1）；雙曲線"
    },
    "5:8:115-數B-11": {
      "id": "5:8:115-數B-11",
      "key": "115-數B-11",
      "book": 5,
      "unit": 8,
      "method": "比較截平面與圓錐軸、母線的角度，依定義區分橢圓、拋物線及雙曲線。",
      "focus": "在相同軸線與頂點下比較大小圓錐開口，依母線與地面的相對位置判斷截痕。",
      "scope": "依本單元方法展開推導；計算沿用學習路徑中較早學過的基本代數與幾何。",
      "steps": [
        "令圓錐半頂角為 β，軸與地面的銳角為 δ。地面截痕在 β<δ 時為橢圓，β=δ 時為拋物線，β>δ 時為雙曲線。",
        "大燈罩照射範圍較大，表示 β大>β小，軸的 δ 則相同。",
        "大者為拋物線時，小者必為橢圓，所以（2）對；小者已為雙曲線時，大者仍必為雙曲線，所以（5）對。",
        "大者為橢圓時小者也是橢圓，（1）錯；大者為雙曲線時小者可能三類，不能斷言拋物線，（3）錯；小者為拋物線則大者為雙曲線，（4）錯。"
      ],
      "answer": "選項（2）、（5）"
    }
